-- ProcFlags 20 = PROC_FLAG_DONE_MELEE_AUTO_ATTACK (0x4)
--                | PROC_FLAG_DONE_SPELL_MELEE_DMG_CLASS (0x10),
-- so Claw / Bite / Gore count alongside white swings.
--
-- No Cooldown, unlike Taste for Blood's 1s ICD: this adds threat only, never
-- damage, so an unthrottled pet cannot turn it into a damage spike.  Threat is
-- the point of the talent and throttling it would make a tanking pet lose
-- aggro on fast swings.

DELETE FROM `spell_proc` WHERE `SpellId` = 200759;
